import React, { useState } from "react";
import { motion } from "framer-motion";
import { BRAND } from "../types";
import { MapPin, Phone, MessageCircle, Send } from "lucide-react";

const WhatsAppIcon = ({ size = 24 }: { size?: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="white">
    <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z"/>
  </svg>
);

export default function Contact() {
  const [formData, setFormData] = useState({ name: "", phone: "", eventType: "", message: "" });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const text = `*New Inquiry - D SAJAWAT Website*\n\n*Name:* ${formData.name}\n*Phone:* ${formData.phone}\n*Event Type:* ${formData.eventType}\n*Message:* ${formData.message}`;
    window.open(`https://wa.me/${BRAND.whatsapp[0]}?text=${encodeURIComponent(text)}`, "_blank");
  };

  return (
    <section id="contact" className="py-24 lg:py-32 bg-gradient-to-b from-amber-50 to-white">
      <div className="container mx-auto px-6">
        {/* Header */}
        <motion.div
          className="text-center mb-16"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
        >
          <motion.div className="flex items-center justify-center gap-4 mb-6">
            <div className="h-px w-12 bg-gradient-to-r from-transparent to-amber-400" />
            <span className="text-sm font-semibold tracking-[0.15em] uppercase text-amber-500">Get In Touch</span>
            <div className="h-px w-12 bg-gradient-to-l from-transparent to-amber-400" />
          </motion.div>
          <h2 className="text-4xl md:text-5xl font-bold text-gray-900" style={{ fontFamily: "Georgia, serif" }}>
            Let&apos;s decorate your <span className="text-amber-500">event</span>
          </h2>
          <p className="mt-6 text-lg text-gray-600 max-w-2xl mx-auto">
            Whether you need a single table cover or bulk supplies - we deliver Pan India with the same care every time.
          </p>
        </motion.div>

        <div className="grid lg:grid-cols-2 gap-12 items-start max-w-6xl mx-auto">
          {/* Left - Info */}
          <motion.div
            initial={{ opacity: 0, x: -50 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.7 }}
            className="space-y-6"
          >
            {/* Location */}
            <motion.div
              className="bg-white rounded-3xl p-6 shadow-lg shadow-gray-100 flex items-center gap-5"
              whileHover={{ y: -4, boxShadow: "0 20px 40px rgba(0,0,0,0.1)" }}
            >
              <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-amber-100 to-amber-200 flex items-center justify-center flex-shrink-0">
                <MapPin size={26} className="text-amber-600" />
              </div>
              <div>
                <span className="text-xs font-semibold uppercase tracking-wider text-amber-500 block mb-1">Location</span>
                <span className="font-medium text-lg text-gray-900">{BRAND.location}</span>
              </div>
            </motion.div>

            {/* Phone */}
            <motion.div
              className="bg-white rounded-3xl p-6 shadow-lg shadow-gray-100 flex items-center gap-5"
              whileHover={{ y: -4, boxShadow: "0 20px 40px rgba(0,0,0,0.1)" }}
            >
              <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-amber-100 to-amber-200 flex items-center justify-center flex-shrink-0">
                <Phone size={26} className="text-amber-600" />
              </div>
              <div>
                <span className="text-xs font-semibold uppercase tracking-wider text-amber-500 block mb-1">Phone</span>
                <div className="flex flex-col sm:flex-row sm:gap-4">
                  <a href={`tel:${BRAND.phones[0]}`} className="font-medium text-lg text-gray-900 hover:text-amber-500 transition-colors">{BRAND.phones[0]}</a>
                  <a href={`tel:${BRAND.phones[1]}`} className="font-medium text-lg text-gray-900 hover:text-amber-500 transition-colors">{BRAND.phones[1]}</a>
                </div>
              </div>
            </motion.div>

            {/* WhatsApp CTA */}
            <motion.a
              href={`https://wa.me/${BRAND.whatsapp[0]}?text=Hi! I visited your website and would like to inquire about D SAJAWAT fabrics.`}
              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center justify-center gap-4 px-8 py-5 bg-gradient-to-r from-green-500 to-green-600 text-white font-semibold rounded-3xl shadow-xl shadow-green-500/30"
              whileHover={{ scale: 1.02, boxShadow: "0 20px 60px rgba(34, 197, 94, 0.4)" }}
              whileTap={{ scale: 0.98 }}
            >
              <WhatsAppIcon size={26} />
              <span className="text-lg">Chat on WhatsApp</span>
            </motion.a>
          </motion.div>

          {/* Right - Form */}
          <motion.div
            initial={{ opacity: 0, x: 50 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.7, delay: 0.2 }}
            className="bg-white rounded-3xl p-8 shadow-xl"
          >
            <h3 className="text-2xl font-bold text-gray-900 mb-8" style={{ fontFamily: "Georgia, serif" }}>
              Send us a message
            </h3>

            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid sm:grid-cols-2 gap-6">
                <div>
                  <label className="text-xs font-semibold uppercase tracking-wider text-gray-500 block mb-2">Your Name *</label>
                  <input
                    type="text"
                    required
                    className="w-full px-5 py-4 rounded-xl border-2 border-gray-100 focus:border-amber-400 focus:ring-4 focus:ring-amber-400/10 transition-all text-gray-800"
                    placeholder="Enter your name"
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  />
                </div>
                <div>
                  <label className="text-xs font-semibold uppercase tracking-wider text-gray-500 block mb-2">Phone *</label>
                  <input
                    type="tel"
                    required
                    className="w-full px-5 py-4 rounded-xl border-2 border-gray-100 focus:border-amber-400 focus:ring-4 focus:ring-amber-400/10 transition-all text-gray-800"
                    placeholder="Your phone number"
                    value={formData.phone}
                    onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                  />
                </div>
              </div>

              <div>
                <label className="text-xs font-semibold uppercase tracking-wider text-gray-500 block mb-2">Event Type</label>
                <select
                  className="w-full px-5 py-4 rounded-xl border-2 border-gray-100 focus:border-amber-400 focus:ring-4 focus:ring-amber-400/10 transition-all text-gray-800 bg-white"
                  value={formData.eventType}
                  onChange={(e) => setFormData({ ...formData, eventType: e.target.value })}
                >
                  <option value="">Select event type</option>
                  <option value="Wedding">Wedding</option>
                  <option value="Corporate Event">Corporate Event</option>
                  <option value="Birthday Party">Birthday Party</option>
                  <option value="Festival">Festival</option>
                  <option value="Other">Other</option>
                </select>
              </div>

              <div>
                <label className="text-xs font-semibold uppercase tracking-wider text-gray-500 block mb-2">Your Message</label>
                <textarea
                  className="w-full px-5 py-4 rounded-xl border-2 border-gray-100 focus:border-amber-400 focus:ring-4 focus:ring-amber-400/10 transition-all text-gray-800 resize-none"
                  rows={4}
                  placeholder="Tell us about your requirements..."
                  value={formData.message}
                  onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                />
              </div>

              <motion.button
                type="submit"
                className="w-full flex items-center justify-center gap-3 px-8 py-4 bg-gradient-to-r from-amber-400 to-amber-500 text-white font-semibold rounded-xl shadow-lg shadow-amber-500/30"
                whileHover={{ scale: 1.02, boxShadow: "0 20px 60px rgba(212, 175, 55, 0.4)" }}
                whileTap={{ scale: 0.98 }}
              >
                <Send size={18} />
                <span>Send via WhatsApp</span>
              </motion.button>
            </form>
          </motion.div>
        </div>
      </div>
    </section>
  );
}
